mapper.update:
UPDATE analytics_outbox
SET lease_until = DATE_ADD(NOW(3), INTERVAL #{seconds} SECOND)
WHERE event_id = #{eventId} AND state = 'SENDING' AND lease_owner = #{leaseOwner}

UPDATE analytics_outbox
SET state = IF(attempts >= #{maxAttempts}, 'REVIEW', 'PENDING'),
    next_attempt_at = DATE_ADD(NOW(3), INTERVAL #{delaySeconds} SECOND),
    lease_owner = NULL, lease_until = NULL, last_error = #{error}
WHERE event_id = #{eventId} AND state = 'SENDING' AND lease_owner = #{leaseOwner}

UPDATE analytics_outbox
SET state = 'REVIEW', lease_owner = NULL, lease_until = NULL, last_error = #{error}
WHERE event_id = #{eventId} AND state = 'SENDING' AND lease_owner = #{leaseOwner}

mapper.select:
SELECT * FROM analytics_outbox


    state = #{state}


ORDER BY created_at DESC, event_id DESC
LIMIT #{limit} OFFSET #{offset}

mapper.delete:
DELETE FROM analytics_outbox
WHERE state = 'SENT' AND sent_at < DATE_SUB(NOW(3), INTERVAL #{days} DAY)
LIMIT #{limit}
